import{_ as a,H as e,f as t,i as r}from"./chunks/framework.Cvt1eIE0.js";const c=JSON.parse('{"title":"第五章 開戦","description":"","frontmatter":{},"headers":[],"relativePath":"story/2-2.md","filePath":"story/2-2.md"}'),o={name:"story/2-2.md"};function i(n,p,s,h,l,d){return e(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="第五章-開戦" tabindex="-1">第五章 開戦 <a class="header-anchor" href="#第五章-開戦" aria-label="Permalink to &quot;第五章 開戦&quot;">​</a></h1><p>王国歴十二年。</p><p>黒曜石の塔から現れた、謎の軍勢。</p><p>その数、数万。</p><p>斥候の報告は、誰もが信じたくない数字だった。</p><p>「エンダーマンの軍隊だと……。」</p><p>スターリンの顔が、初めて強張った。数々の戦いを乗り越えてきた男の顔が、それでも強張った。</p><p>「ただのエンダーマンじゃない。」</p><p>「統率されている。」</p><p>ピックバーグの声は、震えていた。</p><p>「エンダーマンは、本来、群れない種族だ。意志を持って、隊列を組んで、命令に従って動く。これは……。」</p><p>「これは？」</p><p>「軍隊だ。明確な、軍隊だ。」</p><p>王都 GOLDEN BASTION。</p><p>夜を徹して、緊急戦争会議が開かれた。</p><p>戦争大臣。元帥。王立参謀本部。</p><p>居並ぶ全員の顔に、疲労と緊張が滲んでいた。</p><p>「敵の正体は？」</p><p>オーレックスが尋ねる。</p><p>ピックバーグは、古文書を会議室の長机に広げた。羊皮紙の端が、灯りの中で揺れた。</p><p>「黒曜石帝国。」</p><p>「エンドの民が築いた古代文明です。」</p><p>「彼らは数千年前、ネザーとオーバーワールド、両方の世界を征服しかけました。」</p><p>「しかし。」</p><p>「ある日突然、姿を消した。」</p><p>「滅んだはずだったんだ。」</p><p>会議室は、静まり返った。</p><p>蝋燭の芯が、小さく爆ぜる音だけが聞こえた。</p><p>「そして今。」</p><p>「再び現れた。」</p><p>「奴らは、侵略を始めようとしている。」</p><p>誰も、口を開かなかった。</p><p>元帥が、ようやく声を出した。</p><p>「迎え撃つしかない、ということですな。」</p><p>「迎え撃つ。」</p><p>オーレックスは、繰り返した。</p><p>その言葉の重さを、確かめるように。</p><p>「僕たちは、平和を作るために旅をしてきた。」</p><p>「その平和を、守るためにも、戦わなければならない。」</p><p>王座についた時、彼は誓った。力で支配しない、と。</p><p>しかし。</p><p>守るための力と、支配するための力は、違う。</p><p>そう、自分に言い聞かせるしかなかった。</p><hr><h1 id="第六章-エンダーロード" tabindex="-1">第六章 エンダーロード <a class="header-anchor" href="#第六章-エンダーロード" aria-label="Permalink to &quot;第六章 エンダーロード&quot;">​</a></h1><p>数日後。</p><p>北方前線。</p><p>親衛軍と陸軍第一軍団は、敵と激突した。</p><p>最初の数分で、戦況は明らかになった。</p><p>「ぐわぁ！」</p><p>「強い！」</p><p>普通のエンダーマンとは、比べ物にならなかった。</p><p>転移する速度。</p><p>黒曜石の剣の重さと鋭さ。</p><p>そして、恐ろしいほどの冷静さ。</p><p>兵士の悲鳴が、次々と上がる。</p><p>「なんなんだこいつら！」</p><p>スターリンは大斧を振るい、目の前の敵を二体まとめて薙ぎ払った。だが、振り返るたびに、新しい敵が転移してくる。終わりが見えなかった。</p><p>その時。</p><p>戦場の空気が、変わった。</p><p>紫色の雷が、空を割った。</p><p>そして。</p><p>巨大な影が、地に降り立った。</p><p>身長三メートルを超える、巨人だった。</p><p>黒曜石の鎧が、まるで生きているように脈動していた。紫色のマントが、風もないはずのネザーの戦場で、不気味にはためいていた。</p><p>赤く輝く、二つの目。</p><p>兵士たちは、誰一人、動けなかった。恐怖が、足を縫い付けていた。</p><p>「我が名は。」</p><p>「ENDER LORD。」</p><p>「第四軍団司令官。」</p><p>「侵略者よ。」</p><p>「消え去れ。」</p><p>その声には、抑揚がほとんどなかった。だからこそ、余計に恐ろしかった。感情のない声で告げられる死刑宣告。それが、戦場に響いた。</p><p>兵士たちが、後退する。</p><p>「司令官だと……？」</p><p>スターリンが、低く呟いた。</p><p>「つまり。」</p><p>「まだ上がいるってことか。」</p><p>その言葉が、誰の心にも、重くのしかかった。</p><hr><h1 id="第七章-北方防衛戦" tabindex="-1">第七章 北方防衛戦 <a class="header-anchor" href="#第七章-北方防衛戦" aria-label="Permalink to &quot;第七章 北方防衛戦&quot;">​</a></h1><p>ENDER LORD率いる軍勢は、なおも北方要塞へ迫っていた。</p><p>「ここを突破されれば、王国領内だ！」</p><p>元帥が、地図を叩いて叫んだ。</p><p>「絶対に止める！」</p><p>オーレックスは、声を張った。</p><p>「国王陛下！」</p><p>侍従が、慌てて駆け寄った。</p><p>「前線は危険です！どうか、後方からの指揮を！」</p><p>しかし、オーレックスは微笑んだ。</p><p>それは、ずっと昔、路地裏で剣を抜いた時と、同じ微笑みだった。</p><p>「兵士たちだけに戦わせるわけにはいかない。」</p><p>「僕も行く。」</p><p>スターリンは笑った。あの、雷が転がるような豪快な笑い声。</p><p>「待ってました！」</p><p>「君がそう言うと思ったよ。」</p><p>ピックバーグも頷いた。</p><p>「作戦は、できてる。」</p><p>ノートを開く。かつて、村の橋を架けた時と同じ、緻密な図面が、そこに描かれていた。</p><p>「奴らは転移できる。」</p><p>「なら。」</p><p>「転移先を限定すればいい。」</p><p>指が、地図の上を滑る。</p><p>「玄武岩デルタだ。」</p><p>「狭い地形なら、包囲できる。橋頭堡を一点に絞れば、数の利を、こちらが活かせる。」</p><p>「天才。」</p><p>「君は黙って岩を運ぶ担当でいいよ。」</p><p>何年経っても、変わらない。</p><p>それが、不思議と、戦の前の不安を、少しだけ和らげた。</p><hr><h1 id="第八章-三人の英雄" tabindex="-1">第八章 三人の英雄 <a class="header-anchor" href="#第八章-三人の英雄" aria-label="Permalink to &quot;第八章 三人の英雄&quot;">​</a></h1><p>玄武岩デルタ。</p><p>戦場は、すでに炎に包まれていた。</p><p>「突撃ぃ！」</p><p>スターリンが、敵陣へ真っ先に飛び込んだ。</p><p>「うおおおお！！」</p><p>巨大な斧が、唸りを上げて黒曜石兵を吹き飛ばす。一振りごとに、地響きが起きた。</p><p>一方。</p><p>ピックバーグは、後方の指揮台で旗を振った。</p><p>「第三連隊、前進！」</p><p>「砲兵隊、撃て！」</p><p>轟音。</p><p>地が揺れた。敵軍の隊列が、初めて崩れた。</p><p>そして。</p><p>最前線。</p><p>オーレックスは、黄金の剣を構えた。</p><p>剣身に、戦場の炎が反射していた。それは、遠い昔の夜、真紅の森を焼いた炎を、どこか思い出させた。</p><p>「これ以上。」</p><p>「誰も傷つけさせない！」</p><p>黄金の光が、剣から放たれた。一振りごとに、敵が次々となぎ倒されていく。</p><p>しかし。</p><p>その時。</p><p>空間が、裂けた。</p><p>「来たか。」</p><p>ENDER LORD。</p><p>「王よ。」</p><p>「貴様を滅ぼす。」</p><p>「そして。」</p><p>「エンド帝国は再び、世界を支配する。」</p><p>巨大な黒曜石の剣が、振り上げられる。</p><p>黄金の剣が、それを受ける。</p><p>激突。</p><p>ガァァン！！</p><p>衝撃波が、戦場全体を揺らした。兵士たちが、足を踏ん張ってもなお、後ろへ吹き飛ばされた。</p><p>「陛下！」</p><p>スターリンが叫ぶ。</p><p>「オーレックス！」</p><p>ピックバーグも叫ぶ。</p><p>だが。</p><p>ENDER LORDは、笑っていた。</p><p>「面白い。」</p><p>「だが。」</p><p>「これは序章に過ぎぬ。」</p><p>「我らには。」</p><p>「皇帝陛下がおられる。」</p><p>「皇帝……？」</p><p>オーレックスは、目を見開いた。</p><p>「まさか。」</p><p>「まだ上が……。」</p><p>ENDER LORDは、不気味に笑った。</p><p>「震えて待つがいい。」</p><p>「黄金王。」</p><p>「真の絶望を。」</p><p>そして。</p><p>紫色の光と共に、彼は姿を消した。</p><p>戦場に、静寂が訪れた。</p><p>戦いには、勝った。</p><p>しかし。</p><p>三人の顔に、笑顔はなかった。</p><p>「司令官であれかよ……。」</p><p>スターリンが、肩を落として呟いた。</p><p>ピックバーグの顔色は、青ざめていた。</p><p>「まずい。」</p><p>「本当にまずい。」</p><p>「もし、皇帝がいるなら……。」</p><p>オーレックスは、遠くの空を見つめた。</p><p>そこには。</p><p>巨大な紫色の月。</p><p>そして、さらに大きな、転移門。</p><p>「来る。」</p><p>「本当の戦いが。」</p><p>風のないネザーの空に、それでも何か冷たいものが、頬を撫でた気がした。</p><p>こうして。</p><p>黒曜石戦争は、新たな段階へ突入する。</p><p>そして、三人は、まだ知らなかった。</p><p>エンド帝国皇帝。</p><p>ENDER EMPEROR。</p><p>そして。</p><p>その背後に眠る、さらに恐るべき存在の存在を。</p>',189)])])}const E=a(o,[["render",i]]);export{c as __pageData,E as default};
